/**
 * Applying a chosen priority action: playing a land, casting a spell (with auto-payment),
 * moving the companion to hand. The option was generated by `computePriorityOptions`, so
 * legality holds; payment plans are recomputed here and must succeed.
 */

import type { ObjectId } from '@mtg/shared';
import type { DecisionOutcome, GameGen } from '../decisions';
import { emit, debug } from '../log/log';
import { addGeneric, emptyCost, planPayment } from '../mana/cost';
import type { ParsedManaCost } from '../mana/cost';
import { makePermanent, moveObject, removeFromCurrentZone } from '../state/objects';
import { getDefByOracleId, manaSourcesFor } from '../state/queries';
import type { EngineCardObject, EnginePlayerState, GameContext } from '../state/types';
import type { PriorityActionPayload } from './legal';
import { validateChosenTargets } from './legal';

/** Tap sources per plan, add their production to the pool, then deduct `cost`. */
function payCost(ctx: GameContext, player: EnginePlayerState, cost: ParsedManaCost): void {
  const sources = manaSourcesFor(ctx, player.id);
  const plan = planPayment(cost, player.manaPool, sources);
  if (plan === null) {
    throw new Error(`engine bug: cost for ${player.id} became unpayable at application time`);
  }
  for (const cardId of plan.tapCardIds) {
    const perm = ctx.state.battlefield.find((p) => p.cardId === cardId);
    if (perm === undefined) throw new Error('engine bug: payment source vanished');
    perm.tapped = true;
    emit(ctx, 'tapForMana', { name: perm.name, cardId }, player.id);
    const def = getDefByOracleId(ctx, perm.oracleId, perm.name);
    for (const ability of def.manaAbilities) {
      for (const unit of ability.units) {
        // Phase 2 sources produce single-choice units (see manaSourcesFor).
        const sym = unit[0];
        if (sym !== undefined) player.manaPool[sym] += 1;
      }
    }
  }
  // Deduct: exact colored pips, then {C}, then generic (colorless first, then WUBRG).
  const pool = player.manaPool;
  for (const c of ['W', 'U', 'B', 'R', 'G'] as const) {
    if (pool[c] < cost.colored[c]) throw new Error('engine bug: colored payment shortfall');
    pool[c] -= cost.colored[c];
  }
  if (pool.C < cost.colorless) throw new Error('engine bug: colorless payment shortfall');
  pool.C -= cost.colorless;
  let generic = cost.generic;
  for (const sym of ['C', 'W', 'U', 'B', 'R', 'G'] as const) {
    if (generic === 0) break;
    const take = Math.min(generic, pool[sym]);
    pool[sym] -= take;
    generic -= take;
  }
  if (generic > 0) throw new Error('engine bug: generic payment shortfall');
}

/**
 * Apply a non-pass priority action for `player`. Casting puts the spell on the stack
 * (targets chosen at announcement — brief §5.5); the caster retains priority (CR 117.3c).
 */
export function* applyPriorityAction(
  ctx: GameContext,
  player: EnginePlayerState,
  payload: PriorityActionPayload,
  outcome: DecisionOutcome,
): GameGen<void> {
  const s = ctx.state;
  switch (payload.kind) {
    case 'pass':
      throw new Error('engine bug: pass is not applied via applyPriorityAction');

    case 'playLand': {
      const obj = player.hand.find((o) => o.id === payload.objectId);
      if (obj === undefined) throw new Error('engine bug: land to play not in hand');
      player.landsPlayedThisTurn += 1;
      emit(ctx, 'playLand', { player: player.id, name: obj.name, cardId: obj.cardId }, player.id);
      debug(ctx, 'legalActions', `${player.id} plays ${obj.name}`);
      yield* moveObject(ctx, obj, { zone: 'battlefield', controllerId: player.id });
      return;
    }

    case 'castSpell': {
      const fromZone = payload.fromCommand ? player.commandZone : player.hand;
      const obj = fromZone.find((o) => o.id === payload.objectId);
      if (obj === undefined) throw new Error('engine bug: spell to cast not found');
      const def = getDefByOracleId(ctx, obj.oracleId, obj.name);

      const tax = payload.fromCommand ? 2 * (player.commanderCastCount[obj.cardId] ?? 0) : 0;
      const cost = addGeneric(def.manaCost ?? emptyCost(), tax);
      const targets = validateChosenTargets(ctx, def, player.id, outcome.targets);

      payCost(ctx, player, cost);

      if (payload.fromCommand) {
        player.commanderCastCount[obj.cardId] = (player.commanderCastCount[obj.cardId] ?? 0) + 1;
      }

      // The card leaves its zone and becomes a spell on the stack (CR 601.2a).
      removeFromCurrentZone(ctx, obj);
      const spellCard: EngineCardObject = {
        ...obj,
        id: `o-${s.nextObjectNum++}` as ObjectId,
        zone: 'stack',
      };
      s.stack.push({
        id: spellCard.id,
        sourceId: spellCard.id,
        controllerId: player.id,
        kind: 'spell',
        description: `${obj.name}`,
        targets,
        card: spellCard,
        effects: def.spellEffects,
        triggerSpec: null,
        sourceOracleId: obj.oracleId,
        sourceCardId: obj.cardId,
        isCommanderCast: payload.fromCommand,
      });
      emit(
        ctx,
        'castSpell',
        {
          player: player.id,
          name: obj.name,
          cardId: obj.cardId,
          targets,
          fromCommand: payload.fromCommand,
          commanderTax: tax,
        },
        player.id,
      );
      debug(ctx, 'stack', `${player.id} casts ${obj.name}${tax > 0 ? ` (tax {${tax}})` : ''}`, {
        targets,
      });
      return;
    }

    case 'companionToHand': {
      const companion = player.companion;
      if (companion === null || player.companionMovedToHand) {
        throw new Error('engine bug: companion action without a companion');
      }
      payCost(ctx, player, { ...emptyCost(), generic: 3 });
      player.companionMovedToHand = true;
      const handObj: EngineCardObject = {
        ...companion,
        id: `o-${s.nextObjectNum++}` as ObjectId,
        zone: 'hand',
      };
      player.hand.push(handObj);
      player.companion = null;
      emit(ctx, 'companionToHand', { player: player.id, name: companion.name }, player.id);
      return;
    }
  }
}

export { makePermanent };
